/**
 * T41 number-formatting convention (single source of truth):
 *
 * - counts & money bases ......... integers with thousands separators
 *   (`fmtInt`, `Intl.NumberFormat('en-CA')`);
 * - percentages .................. exactly ONE decimal + `%` (`fmtPct`);
 * - minutes ...................... exactly ONE decimal (`fmtNum1` / `fmtMin`);
 * - kilometres ................... route lengths 1 decimal, gap lengths 2
 *   decimals (positional precision matters at sub-km scale);
 * - missing values ............... em dash `—` via the `fallback`.
 *
 * Panels must format every backend-supplied float through these helpers so
 * raw floats (e.g. 14.0616… min, 63.4000…1%) never leak into the UI.
 */
const INT = new Intl.NumberFormat('en-CA');

const isNum = (n: number | null | undefined): n is number =>
  n != null && Number.isFinite(n);

export function fmtInt(n: number | null | undefined, fallback = '—'): string {
  return isNum(n) ? INT.format(Math.round(n)) : fallback;
}

export function fmtNum1(n: number | null | undefined, fallback = '—'): string {
  return isNum(n) ? n.toFixed(1) : fallback;
}

export function fmtPct(n: number | null | undefined, fallback = '—'): string {
  return isNum(n) ? `${n.toFixed(1)}%` : fallback;
}

export function fmtMin(n: number | null | undefined, fallback = '—'): string {
  return isNum(n) ? `${n.toFixed(1)} min` : fallback;
}

/** Signed percentage-point/percent delta for week-over-week callouts. */
export function signed(n: number | null | undefined, fallback = '±0.0'): string {
  if (!isNum(n)) return fallback;
  return `${n > 0 ? '+' : n < 0 ? '−' : '±'}${Math.abs(n).toFixed(1)}`;
}

/**
 * Parse a collector CSV date — plain `yyyymmdd` (20260817) or already-ISO —
 * into a Date at local noon (noon avoids TZ edge shifts). Returns `null` for
 * anything unparseable so callers can bucket it explicitly instead of it
 * silently collapsing into another day's bucket.
 */
export function parseCollectorDate(s: string): Date | null {
  const iso = s.length === 8 && /^\d{8}$/.test(s)
    ? `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}`
    : s;
  const d = new Date(`${iso}T12:00:00`);
  return Number.isNaN(d.getTime()) ? null : d;
}
