import { WifiOff } from 'lucide-react';

/**
 * Shared panel-level async states (T41 items 1–2): one skeleton pattern and
 * one empty-state pattern used by the measured/planned panels so a first-time
 * viewer always sees either data, an honest "no data yet / collector offline"
 * message, or motion that says what is loading — never blank space.
 */

/** Shimmer placeholder shown while a panel's backend query is in flight. */
export function PanelSkeleton({ label }: { label: string }) {
  return (
    <div
      role="status"
      aria-live="polite"
      aria-label={label}
      className="rounded-xl border border-border bg-card p-4"
    >
      <div className="h-3.5 w-40 animate-pulse rounded bg-border" />
      <div className="mt-3 grid grid-cols-2 gap-2.5 sm:grid-cols-5">
        {[0, 1, 2, 3, 4].map((i) => (
          <div key={i} className="rounded-lg border border-border/60 bg-card-hover p-3">
            <div className="h-2.5 w-14 animate-pulse rounded bg-border" />
            <div className="mt-2 h-6 w-16 animate-pulse rounded bg-border" />
          </div>
        ))}
      </div>
      <div className="mt-4 space-y-2">
        {[0, 1, 2].map((i) => (
          <div key={i} className="h-8 animate-pulse rounded bg-card-hover" />
        ))}
      </div>
    </div>
  );
}

interface EmptyStateProps {
  title: string;
  /** Why it's empty + what will fill it (e.g. "run the collector"). */
  hint: string;
  /** Optional reproduction command shown as code. */
  command?: string;
}

/** Honest "nothing here yet" block — never a bare blank area. */
export function EmptyState({ title, hint, command }: EmptyStateProps) {
  return (
    <div
      role="status"
      aria-live="polite"
      className="flex flex-col items-center justify-center rounded-xl border border-dashed border-border bg-card/50 p-8 text-center"
    >
      <WifiOff className="mb-2 h-6 w-6 text-text-muted" aria-hidden="true" />
      <p className="text-sm font-semibold text-text-primary">{title}</p>
      <p className="mt-1.5 max-w-md text-xs leading-relaxed text-text-muted">{hint}</p>
      {command && (
        <code className="mt-2 rounded bg-card-hover px-1.5 py-0.5 text-[10px] text-text-secondary">
          {command}
        </code>
      )}
    </div>
  );
}
